var undefinedToNull = function (obj) {
    // undefined becomes null
    if (obj === undefined) return null;

    // Arrays: transform each element recursively into a new array
    if (Array.isArray(obj)) {
        return obj.map((item) => undefinedToNull(item));
    }

    // Plain objects: transform each value recursively into a new object
    if (obj !== null && typeof obj === "object") {
        const result = {};
        for (const key of Object.keys(obj)) {
            result[key] = undefinedToNull(obj[key]);
        }
        return result;
    }

    // Primitives (numbers, strings, booleans, null) are returned as-is
    return obj;
};
```

*Note: Python has no separate `undefined` value (only `None`), so the JavaScript version is shown; the logic is a recursive deep copy that replaces `undefined` with `null`.*
